"""Central, North, and Southern Africa facts for the generated bank."""

def make(region):
    def s(diff, cat, country, answer, definition, wiki, claim):
        return dict(region=region, difficulty=diff, kind="single", category=cat, country=country, answer=answer, definition=definition, wiki=wiki, claim=claim)
    def m(diff, cat, country, prompt, options, correct, wiki, claim, explanation):
        return dict(region=region, difficulty=diff, kind="multi", category=cat, country=country, answer=options[correct[0]], definition="", wiki=wiki, claim=claim, options=options, correct=correct, prompt=prompt, explanation=explanation)
    def c(diff, cat, country, prompt, options, correct, wiki, claim, explanation):
        return dict(region=region, difficulty=diff, kind="complete", category=cat, country=country, answer=options[correct[0]], definition="", wiki=wiki, claim=claim, options=options, correct=correct, prompt=prompt, explanation=explanation)
    return s, m, c

def pack(region, blocks):
    s, m, c = make(region)
    rows = []
    for category, items in blocks:
        for item in items:
            rows.append(s(item[0], category, item[1], item[2], item[3], item[4], item[5]))
    return rows, m, c

