def rows_from(region, blocks):
    s, _m, _c = make(region)
    rows = []
    for category, items in blocks.items():
        for item in items:
            answer, definition = item[2], item[3]
            blob = f"{answer} {definition}".lower()
            if "skip" in blob or "is not" in blob or answer.lower().startswith("incwala"):
                continue
            rows.append(s(item[0], category, item[1], answer, definition, item[4], item[5]))
    return rows

